/* ------------------------------------------------------------------ */
/* Varios tipos de IGIC en el mismo documento                          */
/* ------------------------------------------------------------------ */

.lines-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 9px;
}
.lines-head > div { min-width: 0; }
.lines-head label { display: block; font-size: inherit; font-weight: 600; color: var(--ink-2); }
.lines-hint {
  margin: 3px 0 0;
  font-size: 12px;
  line-height: 1.45;
  color: var(--ink-3);
}
.lines-head .btn { flex: 0 0 auto; }

.igic-lines { display: flex; flex-direction: column; gap: 8px; }
.igic-line {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 148px 34px;
  gap: 8px;
  align-items: center;
}
.igic-line select { width: 100%; min-width: 0; }
.igic-line .with-suffix { min-width: 0; }
.igic-line .icon-btn {
  justify-self: end;
  color: var(--ink-3);
}
.igic-line .icon-btn:hover { color: #b4342a; background: #fdeceb; }

.lines-sum {
  margin: 9px 0 0;
  padding: 7px 11px;
  border-radius: 9px;
  background: var(--brand-soft, #e6f0ee);
  color: var(--ink-2);
  font-size: 12.5px;
  font-weight: 550;
}

@media (max-width: 620px) {
  .lines-head { flex-direction: column; }
  .igic-line { grid-template-columns: minmax(0, 1fr) 118px 32px; }
}

/* Liquidación de fruta: kilos, precio por kilo y descuentos */
.liq-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr) minmax(0, 1fr);
  gap: 10px;
  margin-bottom: 10px;
}
.liq-grid .field { margin: 0; }
.dto-line {
  grid-template-columns: minmax(0, 1fr) 148px 34px;
}
.dto-line input[type="text"] { width: 100%; min-width: 0; }

@media (max-width: 620px) {
  .liq-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
  .liq-grid .field:first-child { grid-column: 1 / -1; }
  .dto-line { grid-template-columns: minmax(0, 1fr) 108px 32px; }
}
